// Typed access to olympic-analytics.json, generated by scripts/data/build_olympic_analytics.py.
import raw from "./olympic-analytics.json";

export type Segment = "SP" | "FS";
export type Discipline = "Men" | "Women" | "Pairs" | "Ice Dance";

export interface ElementRow {
  no: number;
  code: string;
  family: string;
  bv: number | null;
  goe: number | null;
  score: number | null;
  clean: boolean | null;
  fall: boolean | null;
  secondHalf: boolean;
}

export interface Performance {
  segment: Segment;
  rank: number;
  name: string;
  noc: string;
  tss: number;
  tes: number;
  pcs: number;
  deductions: number;
  baseValue: number | null;
  falls: number;
  components: Record<string, number>;
  elements: ElementRow[];
}

export interface Standing {
  rank: number;
  name: string;
  noc: string;
  total: number;
  sp: number | null;
  fs: number | null;
}

export interface DisciplineData {
  final: Standing[];
  performances: Performance[];
}

export interface RateBlock {
  n: number;
  cleanRate: number | null;
  cleanCi?: [number, number] | null;
  fallRate: number | null;
  meanGoe: number | null;
}

export interface JumpTypeStats extends RateBlock {
  discipline: "Men" | "Women";
  jump: string;
  revolutions: number;
  quarterRate: number;
  underRate: number;
  downgradeRate: number;
  wrongEdgeRate: number | null;
  edgeAttentionRate: number | null;
  meanGoeClean: number | null;
  meanBaseValue: number;
}

export interface AnalyticsData {
  meta: {
    source: string;
    snapshot: string;
    license: string;
    generated: string;
    definitions: Record<string, string>;
  };
  olympics: Record<string, Record<Discipline, DisciplineData>>;
  jumps: {
    scope: { level: string; disciplines: string[]; seasons: string[]; events: number; jumpElements: number; soloJumps: number };
    byType: JumpTypeStats[];
    patterns: {
      segment: (RateBlock & { group: string })[];
      half: (RateBlock & { group: string })[];
      olympics: (RateBlock & { group: string })[];
      elementType: (RateBlock & { group: string })[];
      revolutions: (RateBlock & { discipline: string; revolutions: number })[];
      position: (RateBlock & { position: number })[];
    };
    trends: { discipline: string; season: string; performances: number; attemptsPerProgram: number | null; cleanRate: number | null; n: number }[];
    combos: (RateBlock & { combo: string })[];
    goeHistogram: { from: number; to: number; clean: number; notClean: number }[];
  };
}

export const analytics = raw as unknown as AnalyticsData;
export const OLYMPIC_EVENTS = Object.keys(analytics.olympics);
export const DISCIPLINES: Discipline[] = ["Men", "Women", "Pairs", "Ice Dance"];

/** Pearson correlation and least-squares line y = a + b·x */
export function linearFit(xs: number[], ys: number[]) {
  const n = xs.length;
  const mx = xs.reduce((s, x) => s + x, 0) / n;
  const my = ys.reduce((s, y) => s + y, 0) / n;
  let sxy = 0, sxx = 0, syy = 0;
  for (let i = 0; i < n; i++) {
    sxy += (xs[i] - mx) * (ys[i] - my);
    sxx += (xs[i] - mx) ** 2;
    syy += (ys[i] - my) ** 2;
  }
  const slope = sxy / sxx;
  return { r: sxy / Math.sqrt(sxx * syy), slope, intercept: my - slope * mx };
}

export const isJump = (e: ElementRow) => e.family === "Jump" || e.family === "Jump Combo" || e.family === "Jump Sequence";
